with unpacked as (select id, plan, effective_from, currency, tier_prices, discounts, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price from price_tiers) select case when avg_tier_price >= 28 then 'HIGH' else 'LOW' end as avg_tier_price_tier, approx_percentile(avg_tier_price, array(0.25, 0.5, 0.75)) as avg_tier_price_quartiles, percentile_approx(avg_tier_price, 0.9) as avg_tier_price_p90, count(distinct id) as distinct_ids from unpacked group by case when avg_tier_price >= 28 then 'HIGH' else 'LOW' end
